USE [JamunaBankProcurement];
GO
CREATE OR ALTER PROCEDURE dbo.usp_ProcurementOfficer_GetAssigned @EmployeeId VARCHAR(30)
AS BEGIN SET NOCOUNT ON;
 SELECT DISTINCT h.REQUISITION_ID,h.REQUISITION_NO,h.REQUESTED_DATE,h.TOTAL_ESTIMATED_AMOUNT,h.CURRENT_STATUS,
  (SELECT COUNT(*) FROM dbo.REQUISITION_ITEM x WHERE x.REQUISITION_ID=h.REQUISITION_ID AND x.IS_ACTIVE=1) ITEM_COUNT,
  a.ASSIGNED_TO_EMPLOYEE_ID,CONVERT(BIT,CASE WHEN a.ASSIGNED_TO_EMPLOYEE_ID=@EmployeeId THEN 1 ELSE 0 END) IS_OWNED_BY_CURRENT_USER,
  detail.ASSET_NAMES,o.ORG_UNIT_NAME,h.REQUESTED_BY_EMPLOYEE_ID,u.DISPLAY_NAME REQUESTED_BY_NAME,detail.REQUISITION_TYPES
 FROM dbo.REQUISITION_HEADER h
 JOIN dbo.REQUISITION_ITEM i ON i.REQUISITION_ID=h.REQUISITION_ID AND i.IS_ACTIVE=1
 JOIN dbo.PROC_OFFICER_ASSET_MAP m ON m.ASSET_ID=i.ASSET_ID AND m.EMPLOYEE_ID=@EmployeeId AND m.IS_ACTIVE=1 AND m.EFFECTIVE_FROM<=CONVERT(DATE,SYSUTCDATETIME()) AND(m.EFFECTIVE_TO IS NULL OR m.EFFECTIVE_TO>=CONVERT(DATE,SYSUTCDATETIME()))
 JOIN dbo.REQUISITION_ASSIGNMENT a ON a.REQUISITION_ID=h.REQUISITION_ID AND a.ASSIGNMENT_TYPE='PROCUREMENT_OFFICER_POOL' AND a.IS_CURRENT=1
 JOIN dbo.ORG_UNIT o ON o.ORG_UNIT_ID=h.REQUESTED_ORG_UNIT_ID JOIN dbo.APP_USER_CACHE u ON u.EMPLOYEE_ID=h.REQUESTED_BY_EMPLOYEE_ID
 CROSS APPLY(SELECT STRING_AGG(x.ASSET_NAME,', ')ASSET_NAMES,STRING_AGG(x.REQ_TYPE,', ')REQUISITION_TYPES FROM(SELECT DISTINCT am.ASSET_NAME,ri.REQ_TYPE FROM dbo.REQUISITION_ITEM ri JOIN dbo.ASSET_MASTER am ON am.ASSET_ID=ri.ASSET_ID WHERE ri.REQUISITION_ID=h.REQUISITION_ID AND ri.IS_ACTIVE=1)x)detail
 WHERE h.CURRENT_STATUS='IN_WORKFLOW' AND h.IS_ACTIVE=1 ORDER BY h.REQUESTED_DATE;
END;
GO
CREATE OR ALTER PROCEDURE dbo.usp_ProcurementOfficer_TakeForReview @RequisitionId BIGINT,@ActorEmployeeId VARCHAR(30),@Remarks NVARCHAR(2000)=NULL,@BatchReferenceId UNIQUEIDENTIFIER=NULL
AS BEGIN SET NOCOUNT ON;SET XACT_ABORT ON;BEGIN TRY BEGIN TRAN;
 IF NOT EXISTS(SELECT 1 FROM dbo.REQUISITION_HEADER WITH(UPDLOCK,HOLDLOCK) WHERE REQUISITION_ID=@RequisitionId AND CURRENT_STATUS='IN_WORKFLOW' AND IS_ACTIVE=1) THROW 51003,'Requisition is not in Procurement Officer workflow.',1;
 IF NOT EXISTS(SELECT 1 FROM dbo.REQUISITION_ASSIGNMENT WITH(UPDLOCK,HOLDLOCK) WHERE REQUISITION_ID=@RequisitionId AND ASSIGNMENT_TYPE='PROCUREMENT_OFFICER_POOL' AND IS_CURRENT=1 AND ASSIGNED_TO_EMPLOYEE_ID IS NULL) THROW 51003,'Request is not available for procurement review.',1;
 IF EXISTS(SELECT 1 FROM dbo.REQUISITION_ITEM i WHERE i.REQUISITION_ID=@RequisitionId AND i.IS_ACTIVE=1 AND NOT EXISTS(SELECT 1 FROM dbo.PROC_OFFICER_ASSET_MAP m WHERE m.ASSET_ID=i.ASSET_ID AND m.EMPLOYEE_ID=@ActorEmployeeId AND m.IS_ACTIVE=1 AND m.EFFECTIVE_FROM<=CONVERT(DATE,SYSUTCDATETIME()) AND(m.EFFECTIVE_TO IS NULL OR m.EFFECTIVE_TO>=CONVERT(DATE,SYSUTCDATETIME())))) THROW 51002,'Officer is not mapped to all requisition assets.',1;
 UPDATE dbo.REQUISITION_ASSIGNMENT SET ASSIGNED_TO_EMPLOYEE_ID=@ActorEmployeeId WHERE REQUISITION_ID=@RequisitionId AND ASSIGNMENT_TYPE='PROCUREMENT_OFFICER_POOL' AND IS_CURRENT=1;
 UPDATE dbo.WORKFLOW_INSTANCE SET CURRENT_OWNER_TYPE='EMPLOYEE',CURRENT_OWNER_EMPLOYEE_ID=@ActorEmployeeId,CURRENT_OWNER_ORG_UNIT_ID=NULL,CURRENT_STATUS='TAKEN',MODIFIED_DATE=SYSUTCDATETIME() WHERE REQUISITION_ID=@RequisitionId AND COMPLETED_DATE IS NULL AND CURRENT_STAGE='PROCUREMENT_OFFICER';
 INSERT dbo.APPROVAL_ACTION(REQUISITION_ID,ACTION_TYPE,ACTION_BY_EMPLOYEE_ID,ACTION_ROLE,FROM_STAGE,TO_STAGE,REMARKS,BATCH_REFERENCE_ID)VALUES(@RequisitionId,'PROCUREMENT_OFFICER_TAKE',@ActorEmployeeId,'PROCUREMENT_OFFICER','PROCUREMENT_OFFICER','PROCUREMENT_OFFICER',@Remarks,@BatchReferenceId);
 INSERT dbo.WORKFLOW_HISTORY(REQUISITION_ID,WORKFLOW_RULE_ID,FROM_STAGE,TO_STAGE,ACTION_TYPE,ACTION_BY_EMPLOYEE_ID,REMARKS,BATCH_REFERENCE_ID)SELECT @RequisitionId,WORKFLOW_RULE_ID,'PROCUREMENT_OFFICER','PROCUREMENT_OFFICER','PROCUREMENT_OFFICER_TAKE',@ActorEmployeeId,@Remarks,@BatchReferenceId FROM dbo.WORKFLOW_INSTANCE WHERE REQUISITION_ID=@RequisitionId AND COMPLETED_DATE IS NULL;
 COMMIT;SELECT'000'RESULT_CODE,N'Success'RESULT_MESSAGE,@RequisitionId ENTITY_ID,NULL REFERENCE_NO;
END TRY BEGIN CATCH IF XACT_STATE()<>0 ROLLBACK;SELECT CASE ERROR_NUMBER()WHEN 51002 THEN'003'WHEN 51003 THEN'004'ELSE'999'END RESULT_CODE,ERROR_MESSAGE()RESULT_MESSAGE,@RequisitionId ENTITY_ID,NULL REFERENCE_NO;END CATCH END;
GO
CREATE OR ALTER PROCEDURE dbo.usp_ProcurementOfficer_Approve @RequisitionId BIGINT,@ActorEmployeeId VARCHAR(30),@Remarks NVARCHAR(2000)=NULL,@BatchReferenceId UNIQUEIDENTIFIER=NULL
AS BEGIN SET NOCOUNT ON;SET XACT_ABORT ON;BEGIN TRY BEGIN TRAN;
 DECLARE @status VARCHAR(40),@requester VARCHAR(30);SELECT @status=CURRENT_STATUS,@requester=REQUESTED_BY_EMPLOYEE_ID FROM dbo.REQUISITION_HEADER WITH(UPDLOCK,HOLDLOCK)WHERE REQUISITION_ID=@RequisitionId AND IS_ACTIVE=1;
 IF @status IS NULL THROW 51001,'Requisition not found.',1;IF @status<>'IN_WORKFLOW' THROW 51003,'Invalid workflow state.',1;
 IF NOT EXISTS(SELECT 1 FROM dbo.REQUISITION_ASSIGNMENT WITH(UPDLOCK,HOLDLOCK)WHERE REQUISITION_ID=@RequisitionId AND ASSIGNMENT_TYPE='PROCUREMENT_OFFICER_POOL' AND IS_CURRENT=1 AND ASSIGNED_TO_EMPLOYEE_ID=@ActorEmployeeId) THROW 51002,'Actor does not own this review.',1;
 DECLARE @evaluated TABLE(WORKFLOW_RULE_ID BIGINT,RULE_CODE VARCHAR(40),RULE_NAME NVARCHAR(200),ASSET_ID BIGINT,ASSET_CODE VARCHAR(40),ASSET_NAME NVARCHAR(200),REQ_TYPE VARCHAR(20),MIN_AMOUNT DECIMAL(18,2),MAX_AMOUNT DECIMAL(18,2),CONCERN_DIVISION_ID BIGINT,SETUP_CODE VARCHAR(40),CONCERN_DIVISION_NAME NVARCHAR(200),AUTHORITY_BEFORE_DIVISION BIT,DESTINATION_AFTER_CONCERN VARCHAR(30),PRIORITY_ORDER INT,IS_ACTIVE BIT,EFFECTIVE_FROM DATE,EFFECTIVE_TO DATE,CALCULATED_ROUTE VARCHAR(40));
 DECLARE @asset BIGINT,@type VARCHAR(20),@amount DECIMAL(18,2),@itemCount INT=0;DECLARE items CURSOR LOCAL FAST_FORWARD FOR SELECT ASSET_ID,REQ_TYPE,ESTIMATED_TOTAL_PRICE FROM dbo.REQUISITION_ITEM WHERE REQUISITION_ID=@RequisitionId AND IS_ACTIVE=1;OPEN items;FETCH NEXT FROM items INTO @asset,@type,@amount;WHILE @@FETCH_STATUS=0 BEGIN SET @itemCount+=1;INSERT @evaluated EXEC dbo.usp_WorkflowRule_Evaluate @asset,@type,@amount,NULL;FETCH NEXT FROM items INTO @asset,@type,@amount;END;CLOSE items;DEALLOCATE items;
 IF @itemCount=0 OR(SELECT COUNT(*)FROM @evaluated)<>@itemCount THROW 51000,'Every requisition item must have a matching workflow rule.',1;
 IF(SELECT COUNT(DISTINCT CONCAT(COALESCE(CONCERN_DIVISION_ID,0),'|',CALCULATED_ROUTE))FROM @evaluated)>1 THROW 51000,'Items resolve to incompatible workflow routes.',1;
 DECLARE @rule BIGINT,@division BIGINT,@next VARCHAR(40),@org BIGINT;SELECT TOP(1)@rule=WORKFLOW_RULE_ID,@division=CONCERN_DIVISION_ID,@next=CALCULATED_ROUTE FROM @evaluated;IF @next NOT IN('READY_FOR_PROCUREMENT','PROCUREMENT_AUTHORITY','CONCERN_DIVISION')THROW 51000,'Workflow evaluation returned an invalid destination.',1;SELECT @org=ORG_UNIT_ID FROM dbo.CONCERN_DIVISION_SETUP WHERE CONCERN_DIVISION_ID=@division AND IS_ACTIVE=1;IF @next='CONCERN_DIVISION'AND @org IS NULL THROW 51000,'Concern Division has no active organization setup.',1;
 UPDATE dbo.REQUISITION_ASSIGNMENT SET IS_CURRENT=0,RELEASED_DATE=SYSUTCDATETIME()WHERE REQUISITION_ID=@RequisitionId AND IS_CURRENT=1;
 IF EXISTS(SELECT 1 FROM dbo.WORKFLOW_INSTANCE WHERE REQUISITION_ID=@RequisitionId AND COMPLETED_DATE IS NULL)
  UPDATE dbo.WORKFLOW_INSTANCE SET WORKFLOW_RULE_ID=@rule,CURRENT_STAGE=@next,CURRENT_OWNER_TYPE=CASE WHEN @next='READY_FOR_PROCUREMENT'THEN'NONE'WHEN @next='CONCERN_DIVISION'THEN'ORG_UNIT'ELSE'ROLE_POOL'END,CURRENT_OWNER_EMPLOYEE_ID=NULL,CURRENT_OWNER_ORG_UNIT_ID=CASE WHEN @next='CONCERN_DIVISION'THEN @org END,CURRENT_STATUS=CASE WHEN @next='READY_FOR_PROCUREMENT'THEN'COMPLETED'ELSE'PENDING'END,COMPLETED_DATE=CASE WHEN @next='READY_FOR_PROCUREMENT'THEN SYSUTCDATETIME()END,MODIFIED_DATE=SYSUTCDATETIME()WHERE REQUISITION_ID=@RequisitionId AND COMPLETED_DATE IS NULL;
 ELSE
  INSERT dbo.WORKFLOW_INSTANCE(REQUISITION_ID,WORKFLOW_RULE_ID,CURRENT_STAGE,CURRENT_OWNER_TYPE,CURRENT_OWNER_ORG_UNIT_ID,CURRENT_STATUS,COMPLETED_DATE)VALUES(@RequisitionId,@rule,@next,CASE WHEN @next='READY_FOR_PROCUREMENT'THEN'NONE'WHEN @next='CONCERN_DIVISION'THEN'ORG_UNIT'ELSE'ROLE_POOL'END,CASE WHEN @next='CONCERN_DIVISION'THEN @org END,CASE WHEN @next='READY_FOR_PROCUREMENT'THEN'COMPLETED'ELSE'PENDING'END,CASE WHEN @next='READY_FOR_PROCUREMENT'THEN SYSUTCDATETIME()END);
 IF NOT EXISTS(SELECT 1 FROM dbo.WORKFLOW_INSTANCE WHERE REQUISITION_ID=@RequisitionId AND CURRENT_STAGE=@next AND CURRENT_STATUS=CASE WHEN @next='READY_FOR_PROCUREMENT'THEN'COMPLETED'ELSE'PENDING'END)THROW 51000,'Workflow transition did not update the active workflow instance.',1;
 IF @next<>'READY_FOR_PROCUREMENT'INSERT dbo.REQUISITION_ASSIGNMENT(REQUISITION_ID,ASSIGNMENT_TYPE,ASSIGNED_TO_ORG_UNIT_ID,CREATED_BY)VALUES(@RequisitionId,CASE WHEN @next='CONCERN_DIVISION'THEN'CONCERN_OFFICIAL'ELSE'PROCUREMENT_AUTHORITY_POOL'END,CASE WHEN @next='CONCERN_DIVISION'THEN @org END,@ActorEmployeeId);
 IF @next='CONCERN_DIVISION'AND NOT EXISTS(SELECT 1 FROM dbo.REQUISITION_ASSIGNMENT WHERE REQUISITION_ID=@RequisitionId AND ASSIGNMENT_TYPE='CONCERN_OFFICIAL'AND ASSIGNED_TO_ORG_UNIT_ID=@org AND IS_CURRENT=1)THROW 51000,'Concern Division transition did not create a valid Concern Official assignment.',1;
 INSERT dbo.APPROVAL_ACTION(REQUISITION_ID,ACTION_TYPE,ACTION_BY_EMPLOYEE_ID,ACTION_ROLE,FROM_STAGE,TO_STAGE,REMARKS,BATCH_REFERENCE_ID)VALUES(@RequisitionId,'PROCUREMENT_OFFICER_APPROVE',@ActorEmployeeId,'PROCUREMENT_OFFICER','PROCUREMENT_OFFICER',@next,@Remarks,@BatchReferenceId);INSERT dbo.WORKFLOW_HISTORY(REQUISITION_ID,WORKFLOW_RULE_ID,FROM_STAGE,TO_STAGE,ACTION_TYPE,ACTION_BY_EMPLOYEE_ID,REMARKS,BATCH_REFERENCE_ID)VALUES(@RequisitionId,@rule,'PROCUREMENT_OFFICER',@next,'PROCUREMENT_OFFICER_APPROVE',@ActorEmployeeId,@Remarks,@BatchReferenceId);
 IF @next='READY_FOR_PROCUREMENT'BEGIN UPDATE dbo.REQUISITION_HEADER SET CURRENT_STATUS='READY_FOR_PROCUREMENT',MODIFIED_BY=@ActorEmployeeId,MODIFIED_DATE=SYSUTCDATETIME()WHERE REQUISITION_ID=@RequisitionId;DECLARE @sid BIGINT=(SELECT STATUS_ID FROM dbo.PROCUREMENT_STATUS_MASTER WHERE STATUS_CODE='READY_FOR_PROCUREMENT'AND IS_ACTIVE=1);IF @sid IS NULL THROW 51000,'READY_FOR_PROCUREMENT status is not configured.',1;INSERT dbo.PROCUREMENT_TRACKING(REQUISITION_ID,CURRENT_STATUS_ID)VALUES(@RequisitionId,@sid);DECLARE @pid BIGINT=SCOPE_IDENTITY();INSERT dbo.PROCUREMENT_STATUS_HISTORY(PROCUREMENT_ID,STATUS_ID,CHANGED_BY_EMPLOYEE_ID,REMARKS,BATCH_REFERENCE_ID)VALUES(@pid,@sid,@ActorEmployeeId,@Remarks,@BatchReferenceId);END;
 COMMIT;SELECT'000'RESULT_CODE,N'Success'RESULT_MESSAGE,@RequisitionId ENTITY_ID,@next REFERENCE_NO;
END TRY BEGIN CATCH IF CURSOR_STATUS('local','items')>=0 CLOSE items;IF CURSOR_STATUS('local','items')>-3 DEALLOCATE items;IF XACT_STATE()<>0 ROLLBACK;SELECT CASE ERROR_NUMBER()WHEN 51000 THEN'001'WHEN 51001 THEN'002'WHEN 51002 THEN'003'WHEN 51003 THEN'004'WHEN 2601 THEN'005'WHEN 2627 THEN'005'ELSE'999'END RESULT_CODE,ERROR_MESSAGE()RESULT_MESSAGE,@RequisitionId ENTITY_ID,NULL REFERENCE_NO;END CATCH END;
GO
CREATE OR ALTER PROCEDURE dbo.usp_ProcurementOfficer_Transition @RequisitionId BIGINT,@ActorEmployeeId VARCHAR(30),@Action VARCHAR(10),@Remarks NVARCHAR(2000),@BatchReferenceId UNIQUEIDENTIFIER=NULL
AS BEGIN SET NOCOUNT ON;SET XACT_ABORT ON;BEGIN TRY BEGIN TRAN;DECLARE @requester VARCHAR(30),@status VARCHAR(40),@rule BIGINT;SELECT @requester=REQUESTED_BY_EMPLOYEE_ID,@status=CURRENT_STATUS FROM dbo.REQUISITION_HEADER WITH(UPDLOCK,HOLDLOCK)WHERE REQUISITION_ID=@RequisitionId AND IS_ACTIVE=1;IF @status IS NULL THROW 51001,'Requisition not found.',1;IF @status<>'IN_WORKFLOW'THROW 51003,'Invalid workflow state.',1;IF @Action NOT IN('RETURN','REJECT')OR NULLIF(LTRIM(RTRIM(@Remarks)),'')IS NULL THROW 51000,'A valid action and remarks are required.',1;IF NOT EXISTS(SELECT 1 FROM dbo.REQUISITION_ASSIGNMENT WITH(UPDLOCK,HOLDLOCK)WHERE REQUISITION_ID=@RequisitionId AND ASSIGNMENT_TYPE='PROCUREMENT_OFFICER_POOL'AND IS_CURRENT=1 AND ASSIGNED_TO_EMPLOYEE_ID=@ActorEmployeeId)THROW 51002,'Actor does not own this review.',1;SELECT @rule=WORKFLOW_RULE_ID FROM dbo.WORKFLOW_INSTANCE WHERE REQUISITION_ID=@RequisitionId AND COMPLETED_DATE IS NULL;UPDATE dbo.REQUISITION_ASSIGNMENT SET IS_CURRENT=0,RELEASED_DATE=SYSUTCDATETIME()WHERE REQUISITION_ID=@RequisitionId AND IS_CURRENT=1;UPDATE dbo.REQUISITION_HEADER SET CURRENT_STATUS=CASE WHEN @Action='RETURN'THEN'RETURNED'ELSE'REJECTED'END,MODIFIED_BY=@ActorEmployeeId,MODIFIED_DATE=SYSUTCDATETIME()WHERE REQUISITION_ID=@RequisitionId;UPDATE dbo.WORKFLOW_INSTANCE SET CURRENT_STAGE=CASE WHEN @Action='RETURN'THEN'MAKER'ELSE'END'END,CURRENT_OWNER_TYPE=CASE WHEN @Action='RETURN'THEN'EMPLOYEE'ELSE'NONE'END,CURRENT_OWNER_EMPLOYEE_ID=CASE WHEN @Action='RETURN'THEN @requester END,CURRENT_OWNER_ORG_UNIT_ID=NULL,CURRENT_STATUS=CASE WHEN @Action='RETURN'THEN'RETURNED'ELSE'REJECTED'END,COMPLETED_DATE=CASE WHEN @Action='REJECT'THEN SYSUTCDATETIME()END,MODIFIED_DATE=SYSUTCDATETIME()WHERE REQUISITION_ID=@RequisitionId AND COMPLETED_DATE IS NULL;IF @Action='RETURN'INSERT dbo.REQUISITION_ASSIGNMENT(REQUISITION_ID,ASSIGNMENT_TYPE,ASSIGNED_TO_EMPLOYEE_ID,CREATED_BY)VALUES(@RequisitionId,'MAKER',@requester,@ActorEmployeeId);DECLARE @actionType VARCHAR(50)=CONCAT('PROCUREMENT_OFFICER_',@Action),@to VARCHAR(40)=CASE WHEN @Action='RETURN'THEN'MAKER'ELSE'END'END;INSERT dbo.APPROVAL_ACTION(REQUISITION_ID,ACTION_TYPE,ACTION_BY_EMPLOYEE_ID,ACTION_ROLE,FROM_STAGE,TO_STAGE,REMARKS,BATCH_REFERENCE_ID)VALUES(@RequisitionId,@actionType,@ActorEmployeeId,'PROCUREMENT_OFFICER','PROCUREMENT_OFFICER',@to,@Remarks,@BatchReferenceId);INSERT dbo.WORKFLOW_HISTORY(REQUISITION_ID,WORKFLOW_RULE_ID,FROM_STAGE,TO_STAGE,ACTION_TYPE,ACTION_BY_EMPLOYEE_ID,REMARKS,BATCH_REFERENCE_ID)VALUES(@RequisitionId,@rule,'PROCUREMENT_OFFICER',@to,@actionType,@ActorEmployeeId,@Remarks,@BatchReferenceId);COMMIT;SELECT'000'RESULT_CODE,N'Success'RESULT_MESSAGE,@RequisitionId ENTITY_ID,@to REFERENCE_NO;END TRY BEGIN CATCH IF XACT_STATE()<>0 ROLLBACK;SELECT CASE ERROR_NUMBER()WHEN 51000 THEN'001'WHEN 51001 THEN'002'WHEN 51002 THEN'003'WHEN 51003 THEN'004'ELSE'999'END RESULT_CODE,ERROR_MESSAGE()RESULT_MESSAGE,@RequisitionId ENTITY_ID,NULL REFERENCE_NO;END CATCH END;
GO
CREATE OR ALTER PROCEDURE dbo.usp_ProcurementOfficer_Return @RequisitionId BIGINT,@ActorEmployeeId VARCHAR(30),@Remarks NVARCHAR(2000),@BatchReferenceId UNIQUEIDENTIFIER=NULL AS BEGIN SET NOCOUNT ON;EXEC dbo.usp_ProcurementOfficer_Transition @RequisitionId,@ActorEmployeeId,'RETURN',@Remarks,@BatchReferenceId;END;
GO
CREATE OR ALTER PROCEDURE dbo.usp_ProcurementOfficer_Reject @RequisitionId BIGINT,@ActorEmployeeId VARCHAR(30),@Remarks NVARCHAR(2000),@BatchReferenceId UNIQUEIDENTIFIER=NULL AS BEGIN SET NOCOUNT ON;EXEC dbo.usp_ProcurementOfficer_Transition @RequisitionId,@ActorEmployeeId,'REJECT',@Remarks,@BatchReferenceId;END;
GO
CREATE OR ALTER PROCEDURE dbo.usp_ProcurementOfficer_AddComment @RequisitionId BIGINT,@ReqItemId BIGINT=NULL,@CommentText NVARCHAR(4000),@ActorEmployeeId VARCHAR(30)
AS BEGIN SET NOCOUNT ON;BEGIN TRY IF NULLIF(LTRIM(RTRIM(@CommentText)),'')IS NULL THROW 51000,'Comment text is required.',1;IF NOT EXISTS(SELECT 1 FROM dbo.REQUISITION_HEADER WHERE REQUISITION_ID=@RequisitionId AND IS_ACTIVE=1)THROW 51001,'Requisition not found.',1;IF @ReqItemId IS NOT NULL AND NOT EXISTS(SELECT 1 FROM dbo.REQUISITION_ITEM WHERE REQ_ITEM_ID=@ReqItemId AND REQUISITION_ID=@RequisitionId AND IS_ACTIVE=1)THROW 51000,'Item does not belong to the requisition.',1;IF NOT EXISTS(SELECT 1 FROM dbo.REQUISITION_ASSIGNMENT WHERE REQUISITION_ID=@RequisitionId AND ASSIGNMENT_TYPE='PROCUREMENT_OFFICER_POOL'AND IS_CURRENT=1 AND ASSIGNED_TO_EMPLOYEE_ID=@ActorEmployeeId)THROW 51002,'Only the officer who owns this review may comment.',1;INSERT dbo.COMMENT_NOTE(REQUISITION_ID,REQ_ITEM_ID,COMMENT_TYPE,COMMENT_TEXT,CREATED_BY_EMPLOYEE_ID)VALUES(@RequisitionId,@ReqItemId,'PROCUREMENT_OFFICER',LTRIM(RTRIM(@CommentText)),@ActorEmployeeId);SELECT'000'RESULT_CODE,N'Success'RESULT_MESSAGE,SCOPE_IDENTITY()ENTITY_ID,NULL REFERENCE_NO;END TRY BEGIN CATCH SELECT CASE ERROR_NUMBER()WHEN 51000 THEN'001'WHEN 51001 THEN'002'WHEN 51002 THEN'003'ELSE'999'END RESULT_CODE,ERROR_MESSAGE()RESULT_MESSAGE,@RequisitionId ENTITY_ID,NULL REFERENCE_NO;END CATCH END;
GO
CREATE OR ALTER PROCEDURE dbo.usp_ProcurementOfficer_GetRequisitionDetail @RequisitionId BIGINT,@EmployeeId VARCHAR(30)
AS BEGIN SET NOCOUNT ON;DECLARE @requester VARCHAR(30);SELECT @requester=h.REQUESTED_BY_EMPLOYEE_ID FROM dbo.REQUISITION_HEADER h WHERE h.REQUISITION_ID=@RequisitionId AND h.CURRENT_STATUS='IN_WORKFLOW' AND h.IS_ACTIVE=1 AND NOT EXISTS(SELECT 1 FROM dbo.REQUISITION_ITEM i WHERE i.REQUISITION_ID=h.REQUISITION_ID AND i.IS_ACTIVE=1 AND NOT EXISTS(SELECT 1 FROM dbo.PROC_OFFICER_ASSET_MAP m WHERE m.ASSET_ID=i.ASSET_ID AND m.EMPLOYEE_ID=@EmployeeId AND m.IS_ACTIVE=1 AND m.EFFECTIVE_FROM<=CONVERT(DATE,SYSUTCDATETIME()) AND(m.EFFECTIVE_TO IS NULL OR m.EFFECTIVE_TO>=CONVERT(DATE,SYSUTCDATETIME())))) AND EXISTS(SELECT 1 FROM dbo.REQUISITION_ASSIGNMENT a WHERE a.REQUISITION_ID=h.REQUISITION_ID AND a.ASSIGNMENT_TYPE='PROCUREMENT_OFFICER_POOL' AND a.IS_CURRENT=1);IF @requester IS NULL BEGIN SELECT TOP(0) REQUISITION_ID,REQUISITION_NO,REQUESTED_BY_EMPLOYEE_ID,REQUESTED_ORG_UNIT_ID,CAST(''AS NVARCHAR(200))ORG_UNIT_NAME,REQUESTED_DATE,JUSTIFICATION,TOTAL_ESTIMATED_AMOUNT,CURRENT_STATUS FROM dbo.REQUISITION_HEADER;RETURN;END;EXEC dbo.usp_Requisition_GetMakerDetail @RequisitionId,@requester;END;
GO
CREATE OR ALTER PROCEDURE dbo.usp_History_GetApproval @RequisitionId BIGINT
AS BEGIN SET NOCOUNT ON;SELECT APPROVAL_ID,REQUISITION_ID,REQ_ITEM_ID,ACTION_TYPE,ACTION_BY_EMPLOYEE_ID,ACTION_ROLE,FROM_STAGE,TO_STAGE,ACTION_DATETIME,REMARKS,BATCH_REFERENCE_ID FROM dbo.APPROVAL_ACTION WHERE REQUISITION_ID=@RequisitionId ORDER BY ACTION_DATETIME,APPROVAL_ID;END;
GO
CREATE OR ALTER PROCEDURE dbo.usp_History_GetWorkflow @RequisitionId BIGINT
AS BEGIN SET NOCOUNT ON;SELECT WORKFLOW_HISTORY_ID,REQUISITION_ID,WORKFLOW_RULE_ID,FROM_STAGE,TO_STAGE,ACTION_TYPE,ACTION_BY_EMPLOYEE_ID,ACTION_DATETIME,REMARKS,BATCH_REFERENCE_ID FROM dbo.WORKFLOW_HISTORY WHERE REQUISITION_ID=@RequisitionId ORDER BY ACTION_DATETIME,WORKFLOW_HISTORY_ID;END;
GO
